fn most_frequent(freq: &Map[Str, Int]) -> Str {
  var max = 0;
  var word = "";
  for key in freq.keys() {
    let count = freq.get(&key).unwrap_or(0);
    if count > max {
      max = count;
      word = key;
    }
  }
  return word;
}

fn total_words(freq: &Map[Str, Int]) -> Int {
  var total = 0;
  for val in freq.values() {
    total = total + val;
  }
  return total;
}

fn main() -> Int {
  let freq = Map[Str, Int]();
  freq.insert("a", 3);
  freq.insert("b", 2);
  freq.insert("c", 1);
  let word = most_frequent(&freq);
  return freq.get(&word).unwrap_or(0);
}
